async function requestMarketData(load=false){
  const generation=++marketRequestGeneration,type=activeType,index=activeIndex;
  const asset=markets[type][index],mode=$('#dataMode')?.value||'eod',interval=$('#barInterval')?.value||'daily';
  const params=new URLSearchParams({symbol:asset.providerSymbol||asset.s,type,mode,interval});
  if(asset.upstoxKey)params.set('upstox_key',asset.upstoxKey);
  if(asset.iciciCode)params.set('icici_code',asset.iciciCode);
  if(asset.fyersSymbol)params.set('fyers_symbol',asset.fyersSymbol);
  const headers={accept:'application/json'},access=$('#dashboardMarketAccess')?.value.trim();
  if(access)headers['x-market-access']=access;
  const current=()=>generation===marketRequestGeneration&&type===activeType&&index===activeIndex&&mode===($('#dataMode')?.value||'eod')&&interval===($('#barInterval')?.value||'daily');
  $('#connectionStatus').textContent='Checking…';
  try{
    const response=await fetch(`/api/market-data?${params}`,{headers,cache:'no-store',signal:AbortSignal.timeout(25000)}),data=await response.json();
    if(!current())return;
    if(!response.ok)throw new Error(data.error||'Connection failed');
    if(!Array.isArray(data.rows)||data.rows.length<35)throw new Error('Provider returned insufficient candle history');
    $('#connectionStatus').textContent=load?'Connected':'Connection verified';
    $('#connectionStatus').style.color='var(--green)';
    if(!load){toast('Connection verified. Choose Load selected instrument to update the chart.');return}
    providerMeta=data;importedRows=data.rows;
    $('#sourceMetadata').textContent=`Source: ${data.source} · Delay: ${data.delay}${data.currency?' · '+data.currency:''}${data.spreadBps!=null?' · spread '+data.spreadBps.toFixed(1)+' bps':''}`;
    $('#dataStatus').textContent=`Using ${data.source} · ${data.rows.length} rows · delay ${data.delay}`;
    render();setRiskDefaults();runMonteCarlo();runValidation();calculateIntraday();toast('Provider data loaded');
  }catch(error){
    if(!current())return;
    $('#connectionStatus').textContent='Connection unavailable';
    $('#connectionStatus').style.color='var(--orange)';
    toast((error.name==='TimeoutError'?'Market-data request timed out':error.message)+(location.protocol==='file:'?' · deploy with Pages Functions first':''));
  }
}
