 scalpRanked=scalpQuotes.map(x=>{const range=Math.max(0,x.high-x.low),rangePct=x.last?range/x.last*100:0,spread=Number.isFinite(x.spreadBps)?x.spreadBps:999,trail=scalpTrail.get(x.symbol)||[],microReturns=trail.slice(1).map((v,i)=>(v.p/trail[i].p-1)*10000),microVol=microReturns.length>1?std(microReturns):null,microScore=microVol==null?40:clamp(100-Math.abs(microVol-22)*2.6,0,100),volumeScore=Math.log1p(x.volume||0)/Math.log1p(maxVolume)*100,spreadScore=clamp(100-spread*2.5,0,100),rangeScore=clamp(100-Math.abs(rangePct-2.5)*28,0,100),movePct=x.close?x.netChange/x.close*100:0,position=range?clamp((x.last-x.low)/range,0,1):.5,bias=movePct>=0&&position>=.52?'UP':movePct<0&&position<=.48?'DOWN':'MIXED',directionScore=clamp(Math.abs(position-.5)*180+Math.abs(movePct)*8,0,100),score=Math.round(volumeScore*.32+spreadScore*.28+rangeScore*.18+directionScore*.12+microScore*.1),unitRisk=Math.max(range*.22,x.last*spread/10000*3),stop=bias==='DOWN'?x.last+unitRisk:x.last-unitRisk,target=bias==='DOWN'?x.last-unitRisk*minRR:x.last+unitRisk*minRR,riskUnits=unitRisk?Math.floor(riskCapital/unitRisk):0,exposureUnits=x.last?Math.floor(account*.2/x.last):0,units=Math.max(0,Math.min(riskUnits,exposureUnits)),plannedLoss=units*unitRisk,exposure=units*x.last,eligible=x.volume>0&&spread<=maxSpread&&rangePct>=minRange&&bias!=='MIXED'&&units>0;return {...x,rangePct,spread,movePct,position,bias,score,stop,target,eligible,microVol,observations:trail.length,units,plannedLoss,exposure,minRR}}).filter(x=>(cap==='all'||x.cap===cap)&&x.spread<=maxSpread&&x.rangePct>=minRange).sort((a,b)=>(b.eligible-a.eligible)||(b.score-a.score)).slice(0,50);
