function reviewScalpPlan(symbol){const x=scalpRanked.find(row=>row.symbol===symbol);if(!x)return;riskPlannerType='stocks';riskPlannerExposureCap=.2;$('#accountSize').value=$('#scalpAccount').value;$('#riskPercent').value=$('#scalpRiskPct').value;$('#entryPrice').value=x.last.toFixed(2);$('#stopPrice').value=x.stop.toFixed(2);$('#targetPrice').value=x.target.toFixed(2);updateRisk();$('.risk-planner').scrollIntoView({behavior:'smooth',block:'start'});toast(`${x.symbol} scenario loaded for risk review`)}
